file.content:
        _fail("invalid_input")
        return 4
    # 输出上界（含末尾 LF）在写出前判定；等于上限合法，失败 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


QUERY_DIGEST_KEYS = ("schema", "source_sha256", "query", "records", "next")
QUERY_QUERY_KEYS = ("start", "end", "kind", "applied")
# log-query 的 KIND：*（任意）或 learn/frame/link/member/service/reload/
# rollback（与 log-summary 同口径，仅取静态事件键形，不重演推导）
_QUERY_KINDS = frozenset(
    ("learn", "frame", "link", "member", "service", "reload", "rollback")
)


def _query_prefix_bytes(doc):
    """log-query 末项摘要文本：前五键紧凑 UTF-8 加 LF。"""
    prefix = {key: doc[key] for key in QUERY_DIGEST_KEYS}
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _query_bytes(doc):
    """log-query stdout 载荷：六键紧凑 UTF-8 加 LF。"""
    ordered = {
        key: doc[key]
        for key in QUERY_DIGEST_KEYS + ("sha256",)
    }
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _cmd_log_query(
    log_path, start_token, end_token, kind_token, applied_token,
    cursor_token, count_token, max_log_bytes, max_output_bytes,
):
    # START/END 为 * 或任意长度非负整数（按数学整数比较）；均非 * 时
    # START≤END；APPLIED 取 */true/false；KIND 取 * 或已知七类；
    # CURSOR/COUNT 完全沿用 log-page；格式非法按 usage 退出 2（打开文件前）
    if _FILTER_BOUND_RE.fullmatch(start_token) is None:
        _fail("usage")
        return 2
    if _FILTER_BOUND_RE.fullmatch(end_token) is None:
        _fail("usage")
        return 2
    if kind_token != "*" and kind_token not in _QUERY_KINDS:
        _fail("usage")
        return 2
    if applied_token not in ("*", "true", "false"):
        _fail("usage")
        return 2
    if _PAGE_CURSOR_RE.fullmatch(cursor_token) is None:
        _fail("usage")
        return 2
    if _LIMIT_RE.fullmatch(count_token) is None:
        _fail("usage")
        return 2
    start = None if start_token == "*" else _limit_value(start_token)
    end = None if end_token == "*" else _limit_value(end_token)
    if start is not None and end is not None and start > end:
        _fail("usage")
        return 2
    want_applied = None if applied_token == "*" else (applied_token == "true")
    want_kind = None if kind_token == "*" else kind_token
    count = _limit_value(count_token)
    try:
        with open(log_path, "rb") as handle:
            # 读取与字节边界完全沿用 log-filter：分块至多 65536 字节，
            # 输入上限按原始字节计，等于上限合法
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        # 与 log-page 同一套静态校验与内部摘要核对：顶层/记录键序与
        # 字段类型、config/event 规范键序、event 已知键形、内部 sha256；
        # 不校验配置语义、不重演事件
        log = parse_json(log_raw)
        _validate_log_shape(log)
        source_sha = log["sha256"]
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != source_sha:
            raise InvalidInput("bad log sha256")
        records = log["records"]
        total = len(records)
        if cursor_token == "*":
            # * 从原 LOG records 下标 0 开始
            offset = 0
        else:
            cursor_sha, offset_token = cursor_token.split(":", 1)
            # 游标摘要须等于 LOG.sha256 且 offset≤记录数（沿用 log-page）
            if cursor_sha != source_sha:
                raise InvalidInput("bad cursor sha256")
            offset = _limit_value(offset_token)
            if offset > total:
                raise InvalidInput("bad cursor offset")
        # 从 offset 起扫描，时间闭区间、kind、applied 合取，原序原样取
        # 至多 COUNT 项；matched 记 (原始下标, 原样记录)
        matched = []
        i = offset
        while i < total and len(matched) < count:
            record = records[i]
            if start is None or record["t"] >= start:
                if end is None or record["t"] <= end:
                    if want_kind is None or _event_kind(
                        record["event"]
                    ) == want_kind:
                        if want_applied is None or record[
                            "applied"
                        ] is want_applied:
                            matched.append((i, record))
            i += 1
        # 已收满 COUNT 项且其后仍有匹配项时 next 为 LOG.sha256:<最后返回
        # 项的下一原始下标>（最后匹配项下标 +1）；否则 null。向前只判定
        # 是否仍有匹配，游标本身指最后返回项的紧后原始下标（同 log-page
        # 的“下一下标”，命名空间为原 LOG records 下标）
        nxt = None
        if len(matched) == count:
            last_index = matched[-1][0]
            j = last_index + 1
            while j < total:
                candidate = records[j]
                if (
                    (start is None or candidate["t"] >= start)
                    and (end is None or candidate["t"] <= end)
                    and (
                        want_kind is None
                        or _event_kind(candidate["event"]) == want_kind
                    )
                    and (
                        want_applied is None
                        or candidate["applied"] is want_applied
                    )
                ):
                    nxt = source_sha + ":" + str(last_index + 1)
                    break
                j += 1
        doc = {
            "schema": RECORD_SCHEMA,
            "source_sha256": source_sha,
            # query 固定四键序：输入 * 写 null，其余整数、整数、字符串、布尔
            "query": {
                "start": start,
                "end": end,
                "kind": want_kind,
                "applied": want_applied,
            },
            "records": [record for _, record in matched],
            "next": nxt,
        }
        doc["sha256"] = hashlib.sha256(_query_prefix_bytes(doc)).hexdigest()
        payload = _query_bytes(doc)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    # 输出上界（含末尾 LF）在写出前判定；等于上限合法，失败 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


FDB_DIGEST_KEYS = ("schema", "source_sha256", "offset", "fdb")


def _fdb_prefix_bytes(doc):
    """log-fdb 末项摘要文本：前四键紧凑 UTF-8 加 LF。"""
    prefix = {key: doc[key] for key in FDB_DIGEST_KEYS}
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _fdb_bytes(doc):
    """log-fdb stdout 载荷：五键紧凑 UTF-8 加 LF。"""
    ordered = {
        key: doc[key]
        for key in FDB_DIGEST_KEYS + ("sha256",)
    }
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _cmd_log_fdb(log_path, cursor_token, max_work):
    # CURSOR 沿用 log-page：* 或 <sha256>:<offset>（调用前已按 usage/2
    # 校验）。输入/输出上限固定各 16777216 字节，分块读取与字节边界沿用
    # log-page，等于上限合法
    try:
        with open(log_path, "rb") as handle:
            log_raw = _read_limited(handle, DEFAULT_MAX_LOG_BYTES)
    except OSError:
        _fail("file_not_found")
        return 3
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        # 静态校验与内部摘要核对同 log-page：顶层/记录键序与字段类型、
        # config/event 规范键序、event 已知键形、内部 sha256
        log = parse_json(log_raw)
        _validate_log_shape(log)
        source_sha = log["sha256"]
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != source_sha:
            raise InvalidInput("bad log sha256")
        records = log["records"]
        total = len(records)
        if cursor_token == "*":
            # * 表示 records 长度：offset 取记录数，即重演全部记录
            offset = total
        else:
            cursor_sha, offset_token = cursor_token.split(":", 1)
            # 游标摘要须等于 LOG.sha256 且 offset≤记录数（沿用 log-page）
            if cursor_sha != source_sha:
                raise InvalidInput("bad cursor sha256")
            offset = _limit_value(offset_token)
            if offset > total:
                raise InvalidInput("bad cursor offset")
        # 按 replay 合同先定模式：仅接受 fdb 配置形状，其他模式一律
        # invalid_input/4
        config = log["config"]
        events = [record["event"] for record in log["records"]]
        if _log_mode(config, events) != "fdb":
            raise InvalidInput("bad log mode")
        # 全量语义校验与从空 FDB 重演完全沿用 replay 的 fdb 路径：逐项
        # 核对 t/version/applied/output，重建 LOG 须与原文件逐字节一致
        result, observer = _run_fdb(config, events, True)
        _verify_records(log, events, observer["items"])
        rebuilt = _build_log_doc(config, events, observer["items"])
        if _log_bytes(rebuilt) != log_raw:
            raise InvalidInput("bad log")
        # 仅重演前 offset 条记录求 FDB：独立空映射、无副作用。先逐事件以
        # 老化前表项数 K 计 K+1（等于上限合法，首次超过即抛
        # FdbWorkLimit），再正式重演；offset=0 为空表，表项按 vlan 数值、
        # mac 字典序，项键序 vlan,mac,port,seen（均沿用 simulate）
        ports, age = validate_config(config)
        fdb_events = validate_events(events, ports)
        prefix_events = fdb_events[:offset]
        fdb_work(prefix_events, age, max_work)
        fdb_entries = simulate(prefix_events, age)["fdb"]
        doc = {
            "schema": RECORD_SCHEMA,
            "source_sha256": source_sha,
            "offset": offset,
            "fdb": fdb_entries,
        }
        doc["sha256"] = hashlib.sha256(_fdb_prefix_bytes(doc)).hexdigest()
        payload = _fdb_bytes(doc)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except FdbWorkLimit:
        _fail("fdb_work_limit")
        return 5
    # 输出上界（含末尾 LF）在全部校验与重演之后判定；失败 stdout 为空，
    # 本命令全程只读 LOG
    if len(payload) > DEFAULT_MAX_OUTPUT_BYTES:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


def _cmd_log_diff(
    left_path,
    right_path,
    max_log_bytes=DEFAULT_MAX_LOG_BYTES,
    max_output_bytes=None,
    max_diff_work=DEFAULT_MAX_DIFF_WORK,
):
    if max_output_bytes is None:
        # 调用时解析缺省：测试可在导入后补丁 DEFAULT_MAX_OUTPUT_BYTES
        max_output_bytes = DEFAULT_MAX_OUTPUT_BYTES
    # 先打开两文件，任一失败即停；均可读后按 LEFT、RIGHT 顺序分块读
    try:
        with open(left_path, "rb") as left_handle, open(
            right_path, "rb"
        ) as right_handle:
            # 分块读取与字节边界沿用 log-query：分块至多 65536 字节，
            # 各受首项上限约束，原始字节（含空白）计入，等于上限合法
            left_raw = _read_limited(left_handle, max_log_bytes)
            if left_raw is None:
                _fail("log_limit")
                return 5
            right_raw = _read_limited(right_handle, max_log_bytes)
            if right_raw is None:
                _fail("log_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        # 两份均按 log-query 同一套静态校验与内部摘要核对：顶层/记录键序
        # 与字段类型、config/event 规范键序、event 已知键形、内部 sha256；
        # 不校验配置语义、不重演事件
        left_log = parse_json(left_raw)
        right_log = parse_json(right_raw)
        _validate_log_shape(left_log)
        _validate_log_shape(right_log)
        if hashlib.sha256(
            _log_prefix_bytes(left_log)
        ).hexdigest() != left_log["sha256"]:
            raise InvalidInput("bad log sha256")
        if hashlib.sha256(
            _log_prefix_bytes(right_log)
        ).hexdigest() != right_log["sha256"]:
            raise InvalidInput("bad log sha256")
        # 输出值一律规范化（对象键按 Unicode 码点升序、数组保序）
        left_config = _canonical(left_log["config"])
        right_config = _canonical(right_log["config"])
        left_records = [_canonical(item) for item in left_log["records"]]
        right_records = [_canonical(item) for item in right_log["records"]]
        common = min(len(left_records), len(right_records))
        config_equal = _json_equal(left_config, right_config)
        # 工作量沿用 config-diff 的 S/D：先无副作用预演配置 D；仅当配置
        # 相等时才逐项累加共同前缀记录对 D（含首个不同对），共同前缀后
        # 的长度差另计 1。等于上限合法，首次超过即停，不构造结果文档
        remaining = _diff_work(left_config, right_config, max_diff_work)
        if config_equal:
            index = 0
            while index < common:
                remaining = _diff_work(
                    left_records[index], right_records[index], remaining
                )
                if not _json_equal(
                    left_records[index], right_records[index]
                ):
                    break
                index += 1
            else:
                # 共同前缀全部相等且长度不同：长度差计 1
                if len(left_records) != len(right_records):
                    if remaining < 1:
                        raise DiffWorkLimit
                    remaining -= 1
        # 按 JSON 类型和值比较：对象忽略键序、数组保序。先比 config，
        # 相等后逐项比 records，首个不同即停；共同前缀后的长度差亦不同
        if not config_equal:
            result = {
                "equal": False,
                "at": "config",
                "left": left_config,
                "right": right_config,
            }
        else:
            at = None
            left_value = None
            right_value = None
            index = 0
            while index < common:
                if not _json_equal(
                    left_records[index], right_records[index]
                ):
                    at = index
                    left_value = left_records[index]
                    right_value = right_records[index]
                    break
                index += 1
            if at is None and len(left_records) != len(right_records):
                # 长度不同：at 为公共长度，缺侧 null，另一侧为首条多余记录
                at = common
                if len(left_records) > common:
                    left_value = left_records[common]
                else:
                    right_value = right_records[common]
            if at is None:
                result = {"equal": True, "at": None,
                          "left": None, "right": None}
            else:
                result = {
                    "equal": False,
                    "at": at,
                    "left": left_value,
                    "right": right_value,
                }
        payload = _result_bytes(result)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except DiffWorkLimit:
        _fail("diff_work_limit")
        return 5
    # 输出字节上界（含末尾 LF）写出前判定；等于上限合法，超限时 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


